#!/usr/bin/env python3
import argparse,datetime,hashlib,json,pathlib,shutil,sys

def load_checker(repo):
    sys.path.insert(0,str(repo/'aer-1')); import conformance; return conformance

def sha(p): return 'sha256:'+hashlib.sha256(p.read_bytes()).hexdigest()
def mapping():
    return {'source':{'title':'Regulation (EU) 2024/1689, Article 12, Record-keeping','url':'https://eur-lex.europa.eu/eli/reg/2024/1689/oj/eng','retrieved':'2026-09-29'},'scope_note':'AER-1 fields are evidence-bearing receipt fields. Article 12 does not name this eight-field schema; this mapping identifies how each field can support logging/traceability and where it is not sufficient alone. Legal applicability and sufficiency require a system-specific assessment.','article_12_text':{'12(1)':'High-risk AI systems shall technically allow for the automatic recording of events (logs) over the lifetime of the system.','12(2)':'In order to ensure a level of traceability of the functioning of a high-risk AI system that is appropriate to the intended purpose of the system, logging capabilities shall enable the recording of events relevant for: (a) identifying situations that may result in the high-risk AI system presenting a risk within the meaning of Article 79(1) or in a substantial modification; (b) facilitating the post-market monitoring referred to in Article 72; and (c) monitoring the operation of high-risk AI systems referred to in Article 26(5).','12(3)':'For high-risk AI systems referred to in point 1(a) of Annex III, the logging capabilities shall provide, at a minimum: (a) recording the period of each use; (b) the reference database against which input data has been checked; (c) the input data for which the search has led to a match; and (d) identification of the natural persons involved in verification of results.'},'fields':{'id':{'article_12_support':['12(2)'],'meaning':'Stable event identity supports traceability and correlation.','limitation':'Article 12 does not prescribe a UUID or this field name.'},'receipt_schema_version':{'article_12_support':['12(1)','12(2)'],'meaning':'Identifies the interpretation of the log record so it can remain usable over the system lifetime.','limitation':'Schema versioning alone is not automatic event logging.'},'created_at':{'article_12_support':['12(2)','12(3)(a)'],'meaning':'Records when an event occurred and supports correlation of use periods.','limitation':'A single creation timestamp does not by itself record both start and end of each use as required by 12(3)(a).'},'tool':{'article_12_support':['12(2)(c)'],'meaning':'Identifies the AI/tool component whose operation produced the event.','limitation':'The field does not capture every system identity or deployment context needed for a complete audit.'},'provenance_class':{'article_12_support':['12(2)'],'meaning':'Adds source/context about how the event was produced.','limitation':'It is not the identification of natural persons required by 12(3)(d).'},'canonical_bytes':{'article_12_support':['12(1)','12(2)'],'meaning':'Preserves the exact UTF-8 event payload that was recorded.','limitation':'The payload must be designed to include the events relevant to the intended purpose.'},'output_hash':{'article_12_support':['12(1)','12(2)'],'meaning':'Allows detection of alteration of the recorded payload and supports trustworthy traceability.','limitation':'Integrity evidence does not itself create the underlying log or prove external truth.'},'verification_status':{'article_12_support':['12(2)(b)','12(2)(c)'],'meaning':'Records the receipt validation result for monitoring and review workflows.','limitation':'It is an application status, not a direct Article 12 legal category.'}}}

def worked():
    return [{'example':'Tool execution event','receipt_fields':['id','created_at','tool','canonical_bytes','output_hash'],'clauses':['12(1)','12(2)'],'explanation':'The event ID, timestamp, tool identity, exact payload, and integrity commitment create a traceable record of an operation; they do not alone prove the full lifetime logging capability.'},{'example':'Risk-relevant output','receipt_fields':['canonical_bytes','output_hash','verification_status'],'clauses':['12(2)(a)'],'explanation':'The committed payload can preserve an event relevant to identifying a risk or substantial modification, while the hash makes later alteration detectable.'},{'example':'Post-market review','receipt_fields':['id','receipt_schema_version','created_at','verification_status'],'clauses':['12(2)(b)'],'explanation':'Stable correlation, time, schema interpretation, and validation status support a post-market review trail.'},{'example':'Operation monitoring','receipt_fields':['tool','provenance_class','canonical_bytes'],'clauses':['12(2)(c)'],'explanation':'Component/source context and recorded event bytes support monitoring operation of the system.'},{'example':'Annex III 1(a) biometric context','receipt_fields':['created_at','canonical_bytes','tool','provenance_class'],'clauses':['12(3)(a)','12(3)(b)','12(3)(c)','12(3)(d)'],'explanation':'These fields may carry or commit to required use-period, database, matched-input, and reviewer data inside canonical_bytes, but AER-1 does not automatically satisfy those minimums; implementers must add the required data and an end timestamp/person identity where applicable.'}]

def main():
    ap=argparse.ArgumentParser();ap.add_argument('receipts_dir');ap.add_argument('--repo',required=True);ap.add_argument('--out',required=True);a=ap.parse_args();root=pathlib.Path(a.repo).resolve();src=pathlib.Path(a.receipts_dir).resolve();out=pathlib.Path(a.out).resolve();out.mkdir(parents=True,exist_ok=True);checker=load_checker(root);receipt_out=out/'receipts';receipt_out.mkdir(exist_ok=True);errors=[]; files=sorted(src.glob('*.json'))
    for p in files:
        try:
            r=json.loads(p.read_text()); f=checker.check(r); anchor=r.get('anchor') if isinstance(r,dict) else None
            if isinstance(anchor,dict) and any(k in anchor for k in ('log','leaf_hash','anchored_at','proof')): f += checker.check_disinterested_tier(r)
            if f: errors.append({'file':p.name,'errors':list(dict.fromkeys(f))})
            else: shutil.copy2(p,receipt_out/p.name)
        except Exception as exc:
            errors.append({'file':p.name,'errors':[str(exc)]})
    if errors: raise SystemExit('invalid receipts: '+json.dumps(errors))
    mp=mapping();(out/'article-12-mapping.json').write_text(json.dumps(mp,indent=2));(out/'article-12-mapping.md').write_text('# AER-1 to EU AI Act Article 12 mapping\n\nSource: [Regulation (EU) 2024/1689, Article 12](https://eur-lex.europa.eu/eli/reg/2024/1689/oj/eng). This is an evidence mapping, not legal advice or a claim that an AER-1 receipt alone satisfies Article 12.\n\n## Article text\n\n'+ '\n\n'.join(f'**{k}.** {v}' for k,v in mp['article_12_text'].items())+'\n\n## Field mapping\n\n'+'\n'.join(f'- **{k}** — supports '+', '.join(v['article_12_support'])+'. '+v['meaning']+' Limitation: '+v['limitation'] for k,v in mp['fields'].items())+'\n\n## Five worked examples\n\n'+'\n\n'.join(f"### {i+1}. {x['example']}\n**Fields:** {', '.join(x['receipt_fields'])}\n**Clauses:** {', '.join(x['clauses'])}\n\n{x['explanation']}" for i,x in enumerate(worked()))+'\n')
    summary='# Audit bundle summary\n\nGenerated '+datetime.datetime.now(datetime.timezone.utc).isoformat()+' from '+str(len(files))+' receipts. All receipts passed the canonical AER-1 core checker and structured anchor checks where present. The bundle maps each eight-field receipt field to supporting Article 12 clauses and explicitly records limitations.\n\nReceipts included: '+', '.join(p.name for p in sorted(receipt_out.glob('*.json')))+'\n\nThis bundle is evidence for an audit workflow, not a legal conclusion that Article 12 is satisfied.\n';(out/'SUMMARY.md').write_text(summary)
    entries=[]
    for p in sorted(out.rglob('*')):
        if p.is_file() and p.name!='manifest.json':entries.append({'path':str(p.relative_to(out)),'sha256':sha(p),'bytes':p.stat().st_size})
    manifest={'format':'aer1-eu-ai-act-audit-bundle-v1','generated_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_repo':str(root),'article_12_source':'https://eur-lex.europa.eu/eli/reg/2024/1689/oj/eng','receipt_count':len(files),'files':entries};(out/'manifest.json').write_text(json.dumps(manifest,indent=2));print(f'AUDIT BUNDLE: {len(files)} receipts valid; {len(entries)+1} files written')
if __name__=='__main__':main()
